export function cardIdentityFor(num: string): CardIdentity | undefined {
  return (CARD_IDENTITIES as Readonly<Record<string, CardIdentity>>)[num];
}

export function isDeckIdentityCard(num: string): boolean {
  return cardIdentityFor(num) !== undefined;
}

export function defaultCaseForPartner(partnerNum: string): string {
  const identity = cardIdentityFor(partnerNum);
  return identity?.kind === "partner" ? (identity.defaultCase ?? "D08026") : "D08026";
}
